WITH recent_web_events AS (SELECT * FROM web_events WHERE session_id = 3 AND duration_sec = 324), web_events_stats AS (SELECT event_type, SUM(CASE WHEN event_type = 'search' THEN duration_sec ELSE 0 END) AS search_duration_sec, MAX(duration_sec) AS max_duration_sec FROM recent_web_events GROUP BY event_type) SELECT * FROM web_events_stats WHERE max_duration_sec >= 470 ORDER BY event_type
